    }
}

template <typename MapFn>
void ETSObjectType::CopyPropertyGroupWithBase(PropertyType type, MapFn &&mapFn, const Substitution &subst,
                                              const ETSObjectType *base) const
{
    if (base == nullptr || base == this) {
        return;
    }

    auto &srcMap = (base->*mapFn)();
    for (auto const &[_, prop] : srcMap) {
        (void)_;
        auto *copied = CopyPropertyWithTypeArguments(prop, relation_, &subst);
        EnsurePropertyMapInitialized(type);
        properties_[static_cast<size_t>(type)]->emplace(prop->Name(), copied);
    }

    // Also copy from SuperType (one level up) to pick up inherited fields
    auto *const super = base->SuperType();
    if (super != nullptr && super != base) {
        auto &superMap = (super->*mapFn)();
        for (auto const &[_, prop] : superMap) {
            (void)_;
            EnsurePropertyMapInitialized(type);
            if (properties_[static_cast<size_t>(type)]->find(prop->Name()) ==
                properties_[static_cast<size_t>(type)]->end()) {
                auto *copied = CopyPropertyWithTypeArguments(prop, relation_, &subst);
                properties_[static_cast<size_t>(type)]->emplace(prop->Name(), copied);
            }
        }
    }
}

